from repair_guides.categories import CATEGORIES


def seed_repair_categories(apps, schema_editor):
    category_model = apps.get_model('repair_guides', 'RepairGuideCategory')
    subcategory_model = apps.get_model('repair_guides', 'RepairGuideSubcategory')
    categories_by_slug = {}

    for position, data in enumerate(CATEGORIES):
        category, _ = category_model.objects.update_or_create(
            slug=data['slug'],
            defaults={
                'name': data['name'],
                'description': data['description'],
                'search_terms': list(data['search_terms']),
                'booking_category': data['booking_category'],
                'safety_notice': data['safety'],
                'sort_order': position,
                'is_active': True,
            },
        )
        categories_by_slug[data['slug']] = category
        for item_position, item_name in enumerate(data['item_types']):
            subcategory_model.objects.update_or_create(
                category=category,
                slug=slugify(item_name),
                defaults={
                    'name': item_name,
                    'sort_order': item_position,
                    'is_active': True,
                },
            )

    for data in CATEGORIES:
        category = categories_by_slug[data['slug']]
        category.related_categories.set(
            categories_by_slug[slug]
            for slug in data['related']
            if slug in categories_by_slug
        )


